def solve(arr):
    preserve_pairs = [(5, 3), (3, 0), (5, 2)]
    n = len(arr)
    # Map original index to value
    orig_to_val = {i: arr[i] for i in range(n)}

    # Build adjacency list for constraints: u -> v means u must come before v
    adj = {i: [] for i in range(n)}
    for u, v in preserve_pairs:
        adj[u].append(v)

    # Check for cycles using DFS
    visited = set()
    rec_stack = set()
    has_cycle = False

    def dfs(node):
        nonlocal has_cycle
        visited.add(node)
        rec_stack.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
            elif neighbor in rec_stack:
                has_cycle = True
                return True
        rec_stack.remove(node)
        return False

    for i in range(n):
        if i not in visited:
            if dfs(i):
                break

    if has_cycle:
        # Fallback: just return sorted (though problem implies feasible)
        return sorted(arr)

    # Topological sort
    in_degree = {i: 0 for i in range(n)}
    for u in adj:
        for v in adj[u]:
            in_degree[v] += 1

    queue = [i for i in range(n) if in_degree[i] == 0]
    result = []

    while queue:
        # Sort queue by value to break ties deterministically (ascending order preference)
        queue.sort(key=lambda x: orig_to_val[x])
        u = queue.pop(0)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Extract values in topological order
    return [orig_to_val[i] for i in result]

def solve(arr):
    preserve_pairs = [(0, 2), (3, 0), (5, 0), (1, 5)]

    n = len(arr)
    adj = {i: [] for i in range(n)}
    in_degree = {i: 0 for i in range(n)}

    for i, j in preserve_pairs:
        adj[i].append(j)
        in_degree[j] += 1

    queue = [i for i in range(n) if in_degree[i] == 0]
    result_indices = []

    while queue:
        queue.sort()
        u = queue.pop(0)
        result_indices.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result_indices) != n:
        raise ValueError("Cycle detected in constraints")

    return [arr[i] for i in result_indices]
